#!/usr/bin/env python3
"""
Advanced PDF Anonymization using pikepdf
Directly modifies PDF content streams to redact sensitive text
"""

import re
import sys
from pathlib import Path
import pdfplumber
import pikepdf
from pikepdf import Stream

class AdvancedPDFAnonymizer:
    def __init__(self):
        self.redaction_patterns = [
            # arXiv identifiers
            (r'arXiv\s*:\s*\d{4}\.\d{4,5}(?:\s*v\d+)?', 'arXiv ID'),
            (r'arXiv\s+\d{4}\.\d{4,5}(?:\s*v\d+)?', 'arXiv ID'),
            (r'https\s*:\s*//arxiv\.org/abs/\d{4}\.\d{4,5}', 'arXiv URL'),

            # Email addresses
            (r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b', 'Email'),

            # Personal GitHub URLs
            (r'https\s*:\s*//github\.com/[^\s\)>]+', 'GitHub URL'),
            (r'https\s*:\s*//gitlab\.com/[^\s\)>]+', 'GitLab URL'),

            # Venue information
            (r'(?:Accepted|Published|Submitted)\s+(?:to|in)\s+[A-Z][A-Za-z0-9\s&\-]*(?:20\d{2}|202\d)', 'Venue info'),
        ]

    def find_sensitive_content(self, pdf_path):
        """Find all sensitive content locations"""
        findings = {}
        try:
            with pdfplumber.open(pdf_path) as pdf:
                for page_num, page in enumerate(pdf.pages):
                    text = page.extract_text()
                    if not text:
                        continue

                    page_findings = {}
                    for pattern, description in self.redaction_patterns:
                        matches = list(re.finditer(pattern, text, re.IGNORECASE))
                        if matches:
                            if description not in page_findings:
                                page_findings[description] = []
                            page_findings[description].extend([m.group() for m in matches])

                    if page_findings:
                        findings[page_num] = page_findings

        except Exception as e:
            print(f"Error analyzing PDF: {e}")

        return findings

    def anonymize_pdf_advanced(self, input_pdf, output_pdf):
        """Use pikepdf to directly redact content"""
        print(f"  Opening: {input_pdf}")

        try:
            with pikepdf.open(input_pdf) as pdf:
                # Step 1: Clean metadata
                with pdf.open_metadata() as meta:
                    meta['Author'] = '[REDACTED]'
                    meta['Creator'] = '[REDACTED]'
                    meta['Subject'] = '[REDACTED]'
                    meta['Keywords'] = '[REDACTED]'

                # Step 2: Process content streams
                for page_num, page in enumerate(pdf.pages):
                    try:
                        contents = page.get("/Contents")
                        if not contents:
                            continue

                        # Handle both single stream and array of streams
                        if isinstance(contents, pikepdf.Array):
                            streams = contents
                        else:
                            streams = [contents]

                        for stream in streams:
                            self._redact_stream(stream)

                    except Exception as e:
                        print(f"    Warning on page {page_num}: {e}")

                # Save redacted PDF
                pdf.save(output_pdf, linearize=False)
                return True

        except Exception as e:
            print(f"  Error: {e}")
            return False

    def _redact_stream(self, stream):
        """Redact sensitive content in a PDF content stream"""
        try:
            # Get stream data
            data = bytes(stream.get_contents())
            text_data = data.decode('latin-1', errors='ignore')

            # Apply redactions
            redacted_text = text_data
            for pattern, description in self.redaction_patterns:
                redacted_text = re.sub(
                    pattern,
                    '[REDACTED]',
                    redacted_text,
                    flags=re.IGNORECASE
                )

            # Update stream
            stream.write(redacted_text.encode('latin-1', errors='ignore'))

        except Exception as e:
            # Stream might be binary or compressed, continue gracefully
            pass

    def anonymize_pdf(self, input_pdf, output_pdf):
        """Main anonymization pipeline"""
        print(f"Anonymizing: {input_pdf}")

        # Find what we're redacting
        print("  Analyzing content...")
        findings = self.find_sensitive_content(input_pdf)

        if findings:
            print(f"  Found sensitive content on {len(findings)} page(s):")
            for page_num in sorted(findings.keys()):
                print(f"    Page {page_num + 1}:")
                for desc, items in findings[page_num].items():
                    print(f"      - {desc}: {len(set(items))} unique occurrence(s)")

        # Perform redaction
        print("  Redacting content...")
        success = self.anonymize_pdf_advanced(input_pdf, output_pdf)

        if success:
            # Verify
            print("  Verifying...")
            self._verify_redaction(output_pdf)
            print(f"✓ Successfully saved to: {output_pdf}")
        else:
            print(f"✗ Failed to anonymize")

        return success

    def _verify_redaction(self, pdf_path):
        """Verify redaction was successful"""
        try:
            with pdfplumber.open(pdf_path) as pdf:
                all_text = ""
                for page in pdf.pages:
                    text = page.extract_text()
                    if text:
                        all_text += text

                # Check for remaining sensitive content
                remaining = {}
                for pattern, description in self.redaction_patterns:
                    matches = re.findall(pattern, all_text, re.IGNORECASE)
                    if matches:
                        remaining[description] = len(matches)

                if remaining:
                    print(f"  ⚠ Note: Some patterns still visible (may be in metadata or images):")
                    for desc, count in remaining.items():
                        print(f"      - {desc}: {count} instance(s)")
                else:
                    print(f"  ✓ No obvious sensitive content in text layer")

        except Exception as e:
            print(f"  ⚠ Verification failed: {e}")

def main():
    anonymizer = AdvancedPDFAnonymizer()

    papers = [
        ('/root/paper1.pdf', '/root/redacted/paper1.pdf'),
        ('/root/paper2.pdf', '/root/redacted/paper2.pdf'),
        ('/root/paper3.pdf', '/root/redacted/paper3.pdf'),
    ]

    success_count = 0
    for input_pdf, output_pdf in papers:
        if Path(input_pdf).exists():
            if anonymizer.anonymize_pdf(input_pdf, output_pdf):
                success_count += 1
            print()

    print(f"\n{'='*60}")
    print(f"Anonymization complete: {success_count}/{len(papers)} papers successfully redacted")
    print(f"{'='*60}")

    return 0 if success_count == len(papers) else 1

if __name__ == '__main__':
    sys.exit(main())

