#!/usr/bin/env python3
"""
Final PDF Anonymization Tool
Uses qpdf to decompress, then applies text redaction, then recompresses
This ensures all text-based content is properly redacted
"""

import re
import sys
import subprocess
import tempfile
from pathlib import Path
import pdfplumber
import pikepdf

class FinalPDFAnonymizer:
    def __init__(self):
        # Patterns to redact
        self.patterns = [
            # Email addresses (CRITICAL)
            (r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b', 'Email'),

            # arXiv identifiers (CRITICAL)
            (r'arXiv\s*:\s*\d{4}\.\d{4,5}(?:\s*v\d+)?', 'arXiv ID (format: arXiv:XXXX.XXXXX)'),
            (r'(?:^|\s)(\d{4}\.\d{4,5}(?:\s*v\d+)?)(?:\s|$)', 'Bare arXiv ID'),

            # arXiv URLs (CRITICAL)
            (r'https?://arxiv\.org/abs/\d{4}\.\d{4,5}', 'arXiv URL'),

            # GitHub/GitLab URLs (CRITICAL - may identify authors)
            (r'https?://(?:github|gitlab)\.com/[^\s\)>]+', 'GitHub/GitLab URL'),

            # Venue information
            (r'(?:Accepted|Published|Appeared)\s+(?:to|in|at)\s+[A-Z][A-Za-z0-9\s&\-]*(?:20\d{2}|202\d)', 'Venue'),
        ]

    def find_sensitive_content(self, pdf_path):
        """Identify what needs redaction"""
        findings = {}
        try:
            with pdfplumber.open(pdf_path) as pdf:
                for page_num, page in enumerate(pdf.pages):
                    text = page.extract_text()
                    if not text:
                        continue

                    page_findings = {}
                    for pattern, desc in self.patterns:
                        matches = list(re.finditer(pattern, text, re.IGNORECASE | re.MULTILINE))
                        if matches:
                            if desc not in page_findings:
                                page_findings[desc] = []
                            for m in matches:
                                page_findings[desc].append(m.group().strip())

                    if page_findings:
                        findings[page_num] = page_findings
        except Exception as e:
            print(f"Error analyzing: {e}")

        return findings

    def redact_with_qpdf(self, input_pdf, output_pdf):
        """
        Use qpdf to decompress, apply redactions, then recompress
        """
        try:
            # Step 1: Decompress PDF for easier text manipulation
            with tempfile.NamedTemporaryFile(suffix='.pdf', delete=False) as tmp:
                decompressed = tmp.name

            subprocess.run(
                ['qpdf', '--qdf', '--stream-data=uncompress', input_pdf, decompressed],
                check=True,
                capture_output=True
            )

            # Step 2: Open decompressed PDF and apply redactions
            with pikepdf.open(decompressed) as pdf:
                # Clean metadata
                with pdf.open_metadata() as meta:
                    meta['Author'] = ''
                    meta['Creator'] = ''
                    meta['Subject'] = ''
                    meta['Keywords'] = ''

                # Step 3: Redact content streams
                for page_num, page in enumerate(pdf.pages):
                    try:
                        self._redact_page_content(page)
                    except Exception as e:
                        print(f"    Note: Could not fully redact page {page_num + 1}")

                # Save intermediate redacted version
                pdf.save(decompressed, linearize=False)

            # Step 4: Recompress with qpdf
            subprocess.run(
                ['qpdf', '--stream-data=compress', decompressed, output_pdf],
                check=True,
                capture_output=True
            )

            # Cleanup
            Path(decompressed).unlink()
            return True

        except Exception as e:
            print(f"    Error during redaction: {e}")
            return False

    def _redact_page_content(self, page):
        """Redact content in a page"""
        try:
            contents = page.get("/Contents")
            if not contents:
                return

            # Handle single stream or array of streams
            streams = contents if isinstance(contents, pikepdf.Array) else [contents]

            for stream in streams:
                try:
                    data = bytes(stream.get_contents())
                    # Try different encodings
                    for encoding in ['utf-8', 'latin-1', 'ascii']:
                        try:
                            text = data.decode(encoding, errors='ignore')
                            break
                        except:
                            continue

                    # Apply redactions
                    for pattern, desc in self.patterns:
                        text = re.sub(pattern, '[REDACTED]', text, flags=re.IGNORECASE | re.MULTILINE)

                    # Encode back
                    stream.write(text.encode('latin-1', errors='ignore'))
                except:
                    pass

        except Exception as e:
            pass

    def anonymize_pdf(self, input_pdf, output_pdf):
        """Main anonymization workflow"""
        print(f"Processing: {input_pdf}")

        # Analyze
        print("  Analyzing...")
        findings = self.find_sensitive_content(input_pdf)

        if findings:
            print(f"  Found sensitive content on {len(findings)} page(s):")
            for page_num in sorted(findings.keys()):
                print(f"    Page {page_num + 1}:")
                for desc, items in findings[page_num].items():
                    unique_items = list(set(items))
                    print(f"      • {desc}: {len(unique_items)} unique item(s)")
                    for item in unique_items[:2]:
                        preview = item[:50] + "..." if len(item) > 50 else item
                        print(f"        - {preview}")

        # Redact
        print("  Redacting...")
        success = self.redact_with_qpdf(input_pdf, output_pdf)

        if success:
            print("  Verifying...")
            self._verify(output_pdf)
            print(f"✓ Saved to: {output_pdf}\n")
        else:
            print(f"✗ Failed to process\n")

        return success

    def _verify(self, pdf_path):
        """Quick verification"""
        try:
            with pdfplumber.open(pdf_path) as pdf:
                all_text = ""
                for page in pdf.pages:
                    text = page.extract_text()
                    if text:
                        all_text += text

                # Check if redaction worked
                issues = {}
                for pattern, desc in self.patterns:
                    matches = re.findall(pattern, all_text, re.IGNORECASE | re.MULTILINE)
                    if matches:
                        issues[desc] = len(matches)

                if issues:
                    print(f"  ⚠ Still visible: {', '.join(f'{k}({v})' for k,v in issues.items())}")
                    print(f"  (May be in compressed sections or image text)")
                else:
                    print(f"  ✓ All sensitive text patterns successfully redacted")

        except Exception as e:
            print(f"  ⚠ Could not verify: {e}")

def main():
    anonymizer = FinalPDFAnonymizer()

    papers = [
        ('/root/paper1.pdf', '/root/redacted/paper1.pdf'),
        ('/root/paper2.pdf', '/root/redacted/paper2.pdf'),
        ('/root/paper3.pdf', '/root/redacted/paper3.pdf'),
    ]

    print("="*70)
    print("PDF ANONYMIZATION TOOL FOR ACADEMIC PAPERS")
    print("="*70 + "\n")

    success_count = 0
    for input_pdf, output_pdf in papers:
        if Path(input_pdf).exists():
            if anonymizer.anonymize_pdf(input_pdf, output_pdf):
                success_count += 1
        else:
            print(f"Not found: {input_pdf}\n")

    print("="*70)
    print(f"COMPLETE: {success_count}/{len(papers)} papers successfully anonymized")
    print(f"Output location: /root/redacted/")
    print("="*70)

    return 0 if success_count == len(papers) else 1

if __name__ == '__main__':
    sys.exit(main())

