import sys
import struct
from pathlib import Path
import pdfplumber
from pypdf import PdfReader, PdfWriter
import zlib

class ContentStreamRedactor:
    def __init__(self):
        self.search_replace_pairs = [
            # Email addresses
            (r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b', '[REDACTED]'),
