            # GitLab URLs
            (r'https?://gitlab\.com/[^\s\)>]+', '[REDACTED]'),
        ]

    def decompress_stream(self, stream_data):
        """Attempt to decompress PDF stream"""
        try:
            return zlib.decompress(stream_data)
        except:
            return stream_data

    def compress_stream(self, data):
        """Compress data for PDF storage"""
        return zlib.compress(data)

    def redact_content_stream(self, stream_bytes):
        """Redact sensitive content from a PDF content stream"""
        try:
            # Try to decompress
            decompressed = self.decompress_stream(stream_bytes)

            # Convert to string for pattern matching
            try:
                text = decompressed.decode('latin-1')
            except:
                text = decompressed.decode('utf-8', errors='ignore')

            # Apply redactions using regex
            for pattern, replacement in self.search_replace_pairs:
                text = re.sub(pattern, replacement, text, flags=re.IGNORECASE)

            # Convert back to bytes
            result = text.encode('latin-1', errors='ignore')
            return result

        except Exception as e:
            return stream_bytes

    def redact_pdf(self, input_pdf, output_pdf):
        """Redact sensitive content from PDF"""
        try:
            reader = PdfReader(input_pdf)
            writer = PdfWriter()

            # Clean document info
            writer.add_metadata({})

            # Process each page
            for page_num, page in enumerate(reader.pages):
                try:
                    # Access the content stream
                    if "/Contents" in page:
                        contents = page["/Contents"]

                        # Handle both direct stream and indirect reference
                        if hasattr(contents, 'get_object'):
                            contents = contents.get_object()

                        # Handle array of content streams
                        if isinstance(contents, list):
                            streams = contents
                        else:
