                                # Decompress, redact, recompress
                                stream_data = stream.get_data()
                                redacted = self.redact_content_stream(stream_data)
                                stream._data = self.compress_stream(redacted)
                                stream["/Filter"] = "/FlateDecode"
                            else:
                                # Try direct manipulation
                                try:
                                    stream_data = stream.get_data()
                                    redacted = self.redact_content_stream(stream_data)
                                    stream.set_data(redacted)
                                except:
                                    pass

                except Exception as e:
