                            if desc not in page_findings:
                                page_findings[desc] = []
                            page_findings[desc].extend(matches)

                    if page_findings:
                        findings[page_num] = page_findings
        except Exception as e:
            pass

        return findings

    def process_paper(self, input_pdf, output_pdf):
        """Full processing pipeline"""
        print(f"Processing: {input_pdf}")

