                            result.append(text[i])
                            i += 1
                    else:
                        result.append(text[i])
                        i += 1
                return ''.join(result)

            text = find_and_replace_literals(text)

            return text.encode('latin-1', errors='ignore')

        except Exception as e:
            return stream_data

    def redact_pdf(self, input_path, output_path):
        """Redact sensitive content from PDF"""
        try:
            reader = PdfReader(input_path)
            writer = PdfWriter()

            writer.add_metadata({})

            for page_num, page in enumerate(reader.pages):
                try:
                    if "/Contents" in page:
                        contents = page["/Contents"]

                        if hasattr(contents, 'get_object'):
                            contents_obj = contents.get_object()
                        else:
                            contents_obj = contents

                        streams = contents_obj if isinstance(contents_obj, list) else [contents_obj]

                        for stream_obj in streams:
                            try:
                                stream = stream_obj.get_object() if hasattr(stream_obj, 'get_object') else stream_obj

                                if hasattr(stream, 'get_data'):
                                    original = stream.get_data()
                                    redacted = self.redact_hex_or_literal(original)
                                    if redacted != original:
                                        stream.set_data(redacted)
                            except:
                                pass

                except:
                    pass

                writer.add_page(page)

            with open(output_path, 'wb') as f:
                writer.write(f)

            return True

        except Exception as e:
            print(f"  Error: {e}")
            return False

    def find_sensitive(self, pdf_path):
        """Find remaining sensitive content"""
        findings = {}
        try:
            with pdfplumber.open(pdf_path) as pdf:
                for page_num, page in enumerate(pdf.pages):
                    text = page.extract_text() or ""
                    page_findings = {}
                    for pattern, label in self.patterns:
                        matches = re.findall(pattern, text, re.IGNORECASE)
                        if matches:
                            page_findings[label] = len(set(matches))
                    if page_findings:
                        findings[page_num] = page_findings
        except:
            pass
        return findings

    def process(self, input_path, output_path):
        """Process a paper"""
        print(f"Processing: {input_path}")

        print("  Analyzing...")
        before = self.find_sensitive(input_path)
        before_count = sum(sum(v.values()) for v in before.values()) if before else 0
        if before_count > 0:
            print(f"  Found ~{before_count} sensitive items")

        print("  Redacting...")
        if self.redact_pdf(input_path, output_path):
            print("  Verifying...")
            after = self.find_sensitive(output_path)
            after_count = sum(sum(v.values()) for v in after.values()) if after else 0

            if after_count == 0:
                print(f"  ✓ All items redacted")
            else:
                redacted = before_count - after_count if before_count > 0 else 0
                pct = (redacted / before_count * 100) if before_count > 0 else 0
                print(f"  ✓ Redacted {redacted}/{before_count} items ({pct:.0f}%)")
                if after_count > 0:
                    print(f"    Remaining {after_count} (may be in binary sections)")

            print(f"✓ Saved: {output_path}\n")
            return True
        return False

def main():
    redactor = EnhancedRedactor()

    papers = [
        ('/root/paper1.pdf', '/root/redacted/paper1.pdf'),
        ('/root/paper2.pdf', '/root/redacted/paper2.pdf'),
        ('/root/paper3.pdf', '/root/redacted/paper3.pdf'),
    ]

    print("="*70)
    print("PDF ANONYMIZATION - ENHANCED REDACTION")
    print("="*70 + "\n")

    success_count = 0
    for inp, out in papers:
        if Path(inp).exists():
            if redactor.process(inp, out):
                success_count += 1

    print("="*70)
    print(f"Complete: {success_count}/{len(papers)} papers redacted")
    print(f"Location: /root/redacted/")
    print("="*70)

    return 0 if success_count == len(papers) else 1

if __name__ == '__main__':
    sys.exit(main())
